using System;
class ReactiveSpellChecks {
 static void Check(bool v,string label){if(!v)throw new Exception(label);}
 static void Main(){var a=new AgathysEffect();a.Cast(1,0);Check(a.Retaliation(0,5,true)==5,"melee retaliation");Check(a.Retaliation(0,5,false)==0,"ranged does not retaliate");int snapshot=a.Retaliation(0,5,true);a.Refresh(0,0);Check(snapshot==5&&a.Retaliation(0,10,true)==0,"trigger snapshot survives last temporary hp hit but cannot reactivate ended spell");a.Cast(9,10);Check(a.Retaliation(609,120,true)==45&&a.Retaliation(610,120,true)==0,"upcast and one hour expiry");a.Cast(2,0);Check(a.Retaliation(1,120,true)==10,"other temporary hp can sustain active armor");var c=new CombatState();Check(c.MonsterAttackIsMelee,"default melee");c.UpdateMonsterAttackRange(35);c.MonsterAttackIsMelee=false;Check(c.MonsterAttackRange==35,"attack kind independent of range");c.ApplySliver(false);Check(c.ConsumeSliver(false)&&!c.ConsumeSliver(false),"sliver consumed once");c.ApplySliver(true);c.ExpirePlayerTurnEffects();c.EndRound();Check(c.ConsumeSliver(true),"sliver survives next turn start");c.ApplySliver(false);c.ExpirePlayerTurnEffects();c.EndRound();c.ExpirePlayerTurnEffects();Check(!c.ConsumeSliver(false),"sliver expires caster next turn end");c.ResetBattle();c.ApplyPlayerDamage(10);c.ResolveDeathSave(20,-4);Check(c.PlayerHp==1,"natural twenty death save unaffected by penalty");c.ResetBattle();c.ApplyPlayerDamage(10);c.ResolveDeathSave(1,4);Check(c.DeathFailures==2,"natural one death save unaffected by bonus");c.ResetBattle();c.ApplyPlayerDamage(10);c.ResolveDeathSave(10,-1);Check(c.DeathFailures==1,"death save modifier applies to ordinary result");c.PlayerBlessed=true;c.MonsterBlessed=true;c.ResetBattle();Check(!c.PlayerBlessed&&!c.MonsterBlessed,"reset clears blessing");Check(DirectSpell.Find("Mind Sliver").DiceCount(17,1)==4,"mind sliver scaling");var mark=new MarkEffect();mark.Cast(true,false,1);Check(mark.Applies(false)&&mark.DamageType==8&&mark.CheckDisadvantage(false,1)&&!mark.CheckDisadvantage(false,4)&&!mark.CheckDisadvantage(true,1),"hex target and chosen ability only");mark.Cast(false,true,0);Check(mark.Applies(true)&&mark.DamageType==6&&!mark.CheckDisadvantage(true,0),"hunter mark force damage without hex check penalty");Check(MarkEffect.Duration(true,2)==2400&&MarkEffect.Duration(false,2)==600&&MarkEffect.Duration(true,3)==4800&&MarkEffect.Duration(false,9)==14400,"mark durations by spell and slot");mark.Clear();Check(!mark.Applies(true)&&!mark.Applies(false),"mark ends with concentration");c.PlayerBaned=c.MonsterBaned=true;c.ResetBattle();Check(!c.PlayerBaned&&!c.MonsterBaned,"bane reset");Console.WriteLine("PASS: attack kind, Agathys trigger/expiry/temp HP/upcast, sliver consumption/lifetime, death-save adjustments and blessing reset");}
}
